#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's quoting undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"; fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line). Idempotent. Creates ENV_FILE at mode 0600; writes through a symlink
# and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: the credentials the drift checks need. See docs/maintenance.md.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=7

MCP_REPO="setluca/luca-mcp"
LUCA_REPO="setluca/luca"
HOSTED_SERVER="https://mcp.setluca.com/mcp"
KEYS_PAGE="https://app.setluca.com/app/settings?tab=developer"
TOKEN_PAGE="https://github.com/settings/personal-access-tokens/new"

# key_reaches_server KEY: true when the hosted server lists tools for this key.
key_reaches_server() {
  bunx mcp-inspector --cli --server-url "$HOSTED_SERVER" --transport http \
    --header "Authorization: Bearer $1" --method tools/list --format json >/dev/null 2>&1
}

# key_is_sweep_account KEY: true when the key belongs to the sweep account. A sweep
# calls every write tool on the key's workspace, so the wrong account is a real risk.
key_is_sweep_account() {
  local profile
  profile=$(bunx mcp-inspector --cli --server-url "$HOSTED_SERVER" --transport http \
    --header "Authorization: Bearer $1" --method tools/call --tool-name luca_coach_profile \
    --tool-args-json '{}' --format json 2>/dev/null) || return 1
  [[ "$profile" =~ \"email\":[[:space:]]*\"sweep@setluca\.com\" ]]
}

banner "MCP drift checks setup"

stage "Check your tools"
say "This sets up the credentials for the live tool check, the scheduled sweep,"
say "and the contract sync. No secret is written to disk or shown on screen."
say "You need admin access to $MCP_REPO and $LUCA_REPO, and the sign-in for"
say "sweep@setluca.com."
say "That workspace has to exist first: sign up as sweep@setluca.com, finish onboarding,"
say "and connect a Google calendar on a SetLuca-owned account. Connect no channel or CRM."
if ! command -v gh >/dev/null 2>&1 || ! gh auth status >/dev/null 2>&1; then
  warn "gh is missing or signed out. Run 'gh auth login', then start again."
  exit 1
fi
if [[ ! -x node_modules/.bin/mcp-inspector ]]; then
  warn "Run this from the luca-mcp checkout, after 'bun install'."
  exit 1
fi
pause "Press Enter to continue"

stage "Live check: a low-scope key"
say "CI reads the hosted tool list with this key after every deploy and once a day."
say "Sign in as sweep@setluca.com, so the key belongs to the synthetic workspace."
open_url "$KEYS_PAGE"
step "Under Developer API keys, name a new key 'MCP live check'."
step "Under Access tiers, pick the lowest tier and leave full content off."
step "Under Scopes, tick only analytics:read. Listing tools needs nothing more."
step "Create the key and copy it. It is shown once."
note "If you set an expiry, note the date: the live check fails when the key expires."
ask_secret LUCA_MCP_LIVE_KEY "Paste the key:"
GH_REPO="$MCP_REPO" set_secret LUCA_MCP_LIVE_KEY "$LUCA_MCP_LIVE_KEY"
pause "Press Enter to continue"

stage "Sweep: a full-access key"
say "The weekly sweep calls every tool, writes included, in the sweep workspace only."
say "This secret goes in the private repository, because sweep logs hold record ids."
warn "Create this key only on sweep@setluca.com, never on a coach's workspace."
open_url "$KEYS_PAGE"
step "Under Developer API keys, name a new key 'MCP sweep'."
step "Under Access tiers, pick the highest tier and turn full content on."
step "Under Scopes, tick every scope."
step "Create the key and copy it. It is shown once."
ask_secret LUCA_SWEEP_API_KEY "Paste the key:"
GH_REPO="$LUCA_REPO" set_secret LUCA_SWEEP_API_KEY "$LUCA_SWEEP_API_KEY"
pause "Press Enter to continue"

stage "Contract sync: a token for Luca to open MCP pull requests"
say "After each production deploy, $LUCA_REPO opens a sync pull request in $MCP_REPO."
open_url "$TOKEN_PAGE"
step "Token name: 'Luca to MCP contract sync'. Resource owner: setluca."
step "Repository access: only select repositories, then luca-mcp."
step "Repository permissions: Contents read and write, Pull requests read and write."
step "Generate the token and copy it. An organization policy may ask you to approve it."
note "Note the expiry date: the sync stops when the token expires."
ask_secret MCP_SYNC_TOKEN "Paste the token:"
GH_REPO="$LUCA_REPO" set_secret MCP_SYNC_TOKEN "$MCP_SYNC_TOKEN"
pause "Press Enter to continue"

stage "Release sweep: a token for MCP to start the sweep"
say "Tagging a release in $MCP_REPO starts the sweep in $LUCA_REPO and waits for it."
open_url "$TOKEN_PAGE"
step "Token name: 'MCP release sweep'. Resource owner: setluca."
step "Repository access: only select repositories, then luca."
step "Repository permissions: Actions read and write."
step "Generate the token and copy it. An organization policy may ask you to approve it."
note "Note the expiry date: a release skips the sweep with a warning once it expires."
ask_secret LUCA_REPO_TOKEN "Paste the token:"
GH_REPO="$MCP_REPO" set_secret LUCA_REPO_TOKEN "$LUCA_REPO_TOKEN"
pause "Press Enter to continue"

stage "Let pin-only sync pull requests merge themselves"
say "A sync that changes nothing a tool exposes only moves the pin, so it can merge"
say "itself once 'verify' passes. A sync that changes a tool always waits for a person."
if confirm "Turn on auto-merge for ${MCP_REPO}?"; then
  if gh api -X PATCH "repos/$MCP_REPO" -F allow_auto_merge=true >/dev/null 2>&1; then
    say "Auto-merge is on."
  else
    warn "Couldn't change the setting."
    SKIPPED+=("Turn on auto-merge: Settings → General → Allow auto-merge in $MCP_REPO")
  fi
else
  SKIPPED+=("Pin-only sync pull requests stay open until someone merges them")
fi
pause "Press Enter to continue"

stage "Check it all works"
if key_reaches_server "$LUCA_MCP_LIVE_KEY"; then
  say "The live check key reaches the hosted server."
else
  warn "The live check key could not list tools on $HOSTED_SERVER."
  SKIPPED+=("Check the LUCA_MCP_LIVE_KEY key")
fi
if key_is_sweep_account "$LUCA_SWEEP_API_KEY"; then
  say "The sweep key belongs to sweep@setluca.com."
else
  warn "The sweep key does not belong to sweep@setluca.com, or could not read its profile."
  SKIPPED+=("Revoke the 'MCP sweep' key and make a new one signed in as sweep@setluca.com, then: gh secret set LUCA_SWEEP_API_KEY --repo $LUCA_REPO")
fi
pause "Press Enter to finish"

finish
